import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

// 1. Value Object: Grade
class Grade {
    private final int percentage;
    public Grade(int percentage) {
        if (percentage < 0 || percentage > 100) throw new IllegalArgumentException("Invalid grade");
        this.percentage = percentage;
    }
    public int getPercentage() { return percentage; }
    public boolean isPassing() { return percentage >= 60; }
}

// 2. Domain Entity: Student
class Student {
    private final String studentId;
    private final String name;
    public Student(String studentId, String name) {
        this.studentId = studentId;
        this.name = name;
    }
    public String getStudentId() { return studentId; }
    public String getName() { return name; }
}

// 3. Aggregate Root: Course
class Course {
    private final String courseCode;
    private final String title;
    private final List<Student> enrolledStudents = new ArrayList<>();

    public Course(String courseCode, String title) {
        this.courseCode = courseCode;
        this.title = title;
    }

    public void enroll(Student student) {
        if (student == null) throw new IllegalArgumentException("Student cannot be null");
        enrolledStudents.add(student);
    }

    public List<Student> getEnrolledStudents() {
        return Collections.unmodifiableList(enrolledStudents);
    }
    public String getCourseCode() { return courseCode; }
    public String getTitle() { return title; }
}

public class CoursePlatformApp {
    public static void main(String[] args) {
        Course oopCourse = new Course("CS-201", "Advanced OOP Mastery");
        Student s1 = new Student("STU-01", "Munaf");
        Student s2 = new Student("STU-02", "Keerthana");

        oopCourse.enroll(s1);
        oopCourse.enroll(s2);

        System.out.println("Course: " + oopCourse.getTitle());
        System.out.println("Enrolled Count: " + oopCourse.getEnrolledStudents().size());
    }
}

