import java.util.HashMap;
import java.util.Map;

class Flight {
    private final String flightNumber;
    private int availableSeats;
    public Flight(String flightNumber, int seats) {
        this.flightNumber = flightNumber;
        this.availableSeats = seats;
    }
    public boolean reserveSeat() {
        if (availableSeats <= 0) return false;
        availableSeats--;
        return true;
    }
    public String getFlightNumber() { return flightNumber; }
    public int getAvailableSeats() { return availableSeats; }
}

class Passenger {
    private final String passportNumber;
    private final String fullName;
    public Passenger(String passportNumber, String fullName) {
        this.passportNumber = passportNumber;
        this.fullName = fullName;
    }
    public String getPassportNumber() { return passportNumber; }
    public String getFullName() { return fullName; }
}

// Domain Service orchestrating multi-entity coordination
class BookingCoordinator {
    private final Map<String, String> ticketRegistry = new HashMap<>();

    public String issueTicket(Passenger passenger, Flight flight) {
        if (!flight.reserveSeat()) {
            throw new IllegalStateException("Flight " + flight.getFlightNumber() + " is fully booked!");
        }
        String ticketId = "TKT-" + flight.getFlightNumber() + "-" + passenger.getPassportNumber();
        ticketRegistry.put(ticketId, passenger.getFullName());
        return ticketId;
    }

    public int getTotalTickets() { return ticketRegistry.size(); }
}

public class FlightBookingDemo {
    public static void main(String[] args) {
        Flight flight = new Flight("AI-101", 1);
        Passenger p1 = new Passenger("P99482", "Alice Smith");
        BookingCoordinator coordinator = new BookingCoordinator();

        String ticket = coordinator.issueTicket(p1, flight);
        System.out.println("Issued: " + ticket + " | Remaining seats: " + flight.getAvailableSeats());
    }
}

