import java.util.ArrayList;
import java.util.List;

class LedgerEntry {
    private final String type;
    private final double amount;
    public LedgerEntry(String type, double amount) {
        this.type = type;
        this.amount = amount;
    }
    public String getType() { return type; }
    public double getAmount() { return amount; }
}

class BankAccount {
    private final String accountNumber;
    private double balance;
    private final List<LedgerEntry> entries = new ArrayList<>();

    public BankAccount(String accountNumber) {
        this.accountNumber = accountNumber;
        this.balance = 0.0;
    }

    public void deposit(double amount) {
        if (amount <= 0) return;
        balance += amount;
        entries.add(new LedgerEntry("CREDIT", amount));
    }

    public boolean withdraw(double amount) {
        if (amount <= 0 || amount > balance) return false;
        balance -= amount;
        entries.add(new LedgerEntry("DEBIT", amount));
        return true;
    }

    public double getBalance() { return balance; }
    public int getEntryCount() { return entries.size(); }
    public String getAccountNumber() { return accountNumber; }
}

public class BankAggregateApp {
    public static void main(String[] args) {
        BankAccount acc = new BankAccount("ACC-001");
        acc.deposit(500.0);
        acc.withdraw(200.0);
        acc.withdraw(400.0);

        System.out.println("Final Balance: $" + acc.getBalance());
        System.out.println("Ledger Count: " + acc.getEntryCount());
    }
}

