import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Item {
    private String name;
    private double price;
    private int quantity;
    public Item(String n, double p, int q) { this.name = n; this.price = p; this.quantity = q; }
    public double getPrice() { return price; }
    public int getQuantity() { return quantity; }
}

class ShoppingCart {
    private final List<Item> items = new ArrayList<>();

    public void addItem(Item item) {
        if (item == null || item.getPrice() <= 0 || item.getQuantity() <= 0) {
            throw new IllegalArgumentException("Invalid item");
        }
        items.add(item);
    }

    public List<Item> getItems() {
        return Collections.unmodifiableList(items);
    }

    public double calculateTotal() {
        double t = 0;
        for (Item i : items) t += i.getPrice() * i.getQuantity();
        return t;
    }
}

public class CartBugDemo {
    public static void main(String[] args) {
        ShoppingCart cart = new ShoppingCart();
        try {
            cart.addItem(new Item("Bad", -50.0, -2));
        } catch (IllegalArgumentException e) {
            System.out.println("Caught invalid item");
        }
        cart.addItem(new Item("Apple", 2.0, 3));
        System.out.println("Total: $" + cart.calculateTotal());
    }
}

import java.util.ArrayList;
import java.util.List;

enum RoomType {
    STANDARD(100.0),
    DELUXE(200.0);
    private final double baseRate;
    RoomType(double baseRate) { this.baseRate = baseRate; }
    public double getBaseRate() { return baseRate; }
}

class Room {
    private final int roomNumber;
    private final RoomType type;
    private boolean isOccupied;

    public Room(int roomNumber, RoomType type) {
        this.roomNumber = roomNumber;
        this.type = type;
        this.isOccupied = false;
    }

    public boolean checkIn() {
        if (isOccupied) return false;
        isOccupied = true;
        return true;
    }

    public void checkOut() { isOccupied = false; }
    public int getRoomNumber() { return roomNumber; }
    public RoomType getType() { return type; }
    public boolean isOccupied() { return isOccupied; }
}

class Hotel {
    private final String name;
    private final List<Room> rooms = new ArrayList<>();
    public Hotel(String name) { this.name = name; }
    public void addRoom(Room r) { rooms.add(r); }

    public Room findAvailableRoom(RoomType type) {
        for (Room r : rooms) {
            if (r.getType() == type && !r.isOccupied()) {
                return r;
            }
        }
        return null;
    }
}

public class HotelApp {
    public static void main(String[] args) {
        Hotel hotel = new Hotel("Grand Palace");
        Room r101 = new Room(101, RoomType.STANDARD);
        Room r201 = new Room(201, RoomType.DELUXE);
        hotel.addRoom(r101);
        hotel.addRoom(r201);

        Room booked = hotel.findAvailableRoom(RoomType.STANDARD);
        booked.checkIn();
        System.out.println("Booked Room: " + booked.getRoomNumber());

        Room nextStandard = hotel.findAvailableRoom(RoomType.STANDARD);
        System.out.println("Next Standard available: " + (nextStandard == null ? "None" : "Found"));
    }
}
